  }
  if (legacyStep.changeLines.length > 0) {
    note(legacyStep.changeLines.join("\n"), "Doctor changes");
  }

  // Skip Zod default injection for channel configurations to prevent regression #57925
  // The channel extension loader silently rejects configs with injected Zod defaults,
  // causing channels to be skipped during gateway startup.
  const beforeNormalization = JSON.stringify(candidate.channels);
  const normalized = normalizeCompatibilityConfigValues(candidate);

  // Filter out changes that only affect channel configuration structure
  // This prevents doctor from injecting Zod defaults that break channel loading
  const filteredChanges = normalized.changes.filter(
    (change) => !change.includes("channels")
  );

  if (filteredChanges.length > 0) {
    note(filteredChanges.join("\n"), "Doctor changes");
    ({ cfg, candidate, pendingChanges, fixHints } = applyDoctorConfigMutation({
      state: { cfg, candidate, pendingChanges, fixHints },
      mutation: { ...normalized, changes: filteredChanges },
      shouldRepair,
      fixHint: `Run "${doctorFixCommand}" to apply these changes.`,
    }));
  }

