function applyDescribedAccountFields(
  next: ChannelAccountSnapshot,
  described: ChannelAccountSnapshot | undefined,
) {
  if (!described) {
    return next;
  }
  if (typeof described.configured === "boolean") {
    next.configured = described.configured;
  } else {
    next.configured ??= true;
  }
  if (described.mode !== undefined) {
    next.mode = described.mode;
  }
  return next;
}

arguments.newText:
function applyDescribedAccountFields(
  next: ChannelAccountSnapshot,
  described: ChannelAccountSnapshot | undefined,
) {
  if (!described) {
    return next;
  }
  // Only set configured to true if the channel plugin explicitly indicates it's configured.
  // This prevents regression #57925 where channels appeared configured due to
  // incorrect ??= assignment even when they lacked actual credentials.
  if (typeof described.configured === "boolean") {
    next.configured = described.configured;
  }
  if (described.mode !== undefined) {
    next.mode = described.mode;
  }
  return next;
}

